// SPDX-License-Identifier: MIT
pragma solidity 0.6.12;
pragma experimental ABIEncoderV2;

import "forge-std/Test.sol";
import "../src/Caramel.sol";

contract CaramelTest is Test {
    Caramel token;
    address owner = address(0x1);
    address alice = address(0x2);
    address bob = address(0x3);
    address carol = address(0x4);

    function setUp() public {
        vm.startPrank(owner);
        token = new Caramel();
        token.mint(alice, 1000 * 10**18);
        vm.stopPrank();
    }

    function testTransferFromExceedsAllowance() public {
        uint256 amountToTransfer = 100 * 10**18;
        uint256 expectedBurn = 2 * 10**18; // 2% of 100 tokens

        // Alice approves Bob to spend only 98 tokens
        vm.prank(alice);
        token.approve(bob, 98 * 10**18);

        // Record initial balances and total supply
        uint256 initialAliceBalance = token.balanceOf(alice);
        uint256 initialCarolBalance = token.balanceOf(carol);
        uint256 initialTotalSupply = token.totalSupply();

        // Bob transfers 100 tokens from Alice to Carol
        vm.prank(bob);
        token.transferFrom(alice, carol, amountToTransfer);

        // Verify Alice lost 100 tokens
        uint256 aliceLoss = initialAliceBalance - token.balanceOf(alice);
        assertEq(aliceLoss, amountToTransfer, "Alice lost 100 tokens, exceeding her 98 token allowance");

        // Verify Carol received 98 tokens
        uint256 carolGain = token.balanceOf(carol) - initialCarolBalance;
        assertEq(carolGain, amountToTransfer - expectedBurn, "Carol should receive 98 tokens (100 - 2% burn)");

        // Verify total supply decreased by 2 tokens (burn)
        uint256 supplyReduction = initialTotalSupply - token.totalSupply();
        assertEq(supplyReduction, expectedBurn, "Total supply should decrease by 2 tokens (burn)");
    }
}
